 @Test void tc04_parallelRequestsCreateOneLiveChange()throws Exception{var a=active();extension(a,end(a.contract()));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);AtomicInteger ok=new AtomicInteger();List<Future<?>> tasks=new ArrayList<>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{try{start.await();extension(a);ok.incrementAndGet();}catch(Exception ignored){}}));start.countDown();for(var t:tasks)t.get(20,TimeUnit.SECONDS);pool.shutdownNow();assertThat(ok.get()).isOne();assertThat(count("contract_change_requests","contract_id="+a.contract())).isOne();}
