 @Test void tc06_priceChangesOnlyFromEffectiveDateAndSplitsMidMonth(){var a=active();LocalDate month=LocalDate.now().withDayOfMonth(1),effective=month.plusDays(15);f.db.sql("INSERT INTO billing_rate_versions(contract_id,code,effective_date,unit_price,reference,reason,actor_id) VALUES(:id,'RENT',:date,2700000,'ANNEX','Agreed',1)").param("id",a.contract()).param("date",effective).update();assertThat(b.billing.price(a.contract(),"RENT",effective.minusDays(1),n("2500000"))).isEqualByComparingTo("2500000");assertThat(b.billing.rentForPeriod(a.contract(),n("2500000"),month,month,month.plusMonths(1),"ACTUAL_DAYS")).isEqualByComparingTo(n("2500000").multiply(n("15")).add(n("2700000").multiply(BigDecimal.valueOf(month.lengthOfMonth()-15))).divide(BigDecimal.valueOf(month.lengthOfMonth()),2,java.math.RoundingMode.HALF_UP));}
