 @Test void tc15_rentIntervalsUseSeparatePrices(){LocalDate month=LocalDate.now().withDayOfMonth(1);assertThat(MonthlyBillingService.rent(n("2500000"),month,month,month.plusDays(15),"ACTUAL_DAYS").add(MonthlyBillingService.rent(n("3000000"),month,month.plusDays(15),month.plusMonths(1),"ACTUAL_DAYS"))).isEqualByComparingTo(n("2500000").multiply(n("15")).add(n("3000000").multiply(BigDecimal.valueOf(month.lengthOfMonth()-15))).divide(BigDecimal.valueOf(month.lengthOfMonth()),2,java.math.RoundingMode.HALF_UP));}
 @Test void tc16_transferNeverReassignsOldInvoice(){var a=b.active("0",false);long inv=b.oldDebt(a,"500000");long id=move(a,destination(a),"0");agree(id);prepare(id);assertThat(count("invoices","id="+inv+" AND contract_id="+a.contract())).isOne();assertThat(count("invoices","contract_id="+target(id))).isZero();}
 @Test void tc17_realDepositRemainderMovesWithoutCash(){var a=b.active("3000000",false);b.oldDebt(a,"500000");long id=move(a,destination(a),"4000000");agree(id);prepare(id);settle(a,id);f.run(()->changes.transferDeposit(f.owner,id,new MoveDeposit(version(id),n("2500000"),f.key(),"Transfer agreed remaining funds")));assertThat(f.balance(f.contractDeposit(target(id)))).isEqualByComparingTo("2500000");assertThat(f.balance(a.deposit())).isZero();assertThat(count("payments","property_id="+a.property())).isZero();}
 @Test void tc18_transferRetryDoesNotPostTwice(){var a=b.active("1000000",false);long id=move(a,destination(a),"1000000");agree(id);prepare(id);settle(a,id);String key=f.key();var r=new MoveDeposit(version(id),n("1000000"),key,"Agreed");f.run(()->changes.transferDeposit(f.owner,id,r));f.run(()->changes.transferDeposit(f.owner,id,r));assertThat(count("deposit_transactions","deposit_id="+a.deposit()+" AND transaction_type='TRANSFER_OUT'")).isOne();}
 @Test void tc19_failedPreparationRollsBackCheckoutAndTarget(){var a=b.active("0",false);long id=move(a,destination(a),"0");agree(id);assertThatThrownBy(()->f.run(()->{prepare(id);throw new IllegalStateException("Downstream failure");})).isInstanceOf(IllegalStateException.class);assertThat(q(id).get("target_contract_id")).isNull();assertThat(count("rental_checkouts","contract_id="+a.contract())).isZero();assertThat(count("rooms","id="+a.room()+" AND status='OCCUPIED'")).isOne();}
 @Test void tc20_oldResidencePreserved(){var a=b.active("0",false);long id=move(a,destination(a),"0");agree(id);prepare(id);settle(a,id);assertThat(count("tenant_residences","contract_id="+a.contract()+" AND status='MOVED_OUT'")).isOne();}
 @Test void tc21_fullTransferCompletesAfterOldFinanceAndNewCheckin(){var a=b.active("0",false);long id=move(a,destination(a),"0");agree(id);prepare(id);settle(a,id);f.run(()->f.ledger.closeCheckout(f.owner,a.deposit()));checkin(target(id));f.run(()->changes.completeMove(f.owner,id,new Action(version(id),"Both handovers and finances complete")));assertThat(q(id).get("status")).isEqualTo("COMPLETED");assertThat(count("tenant_residences","contract_id="+target(id)+" AND status='ACTIVE'")).isOne();}
 @Test void tc22_representativeRequiresBothTenantsAndKeepsSigner(){var a=active();long person=occupant(a);var newParty=newUser(person);long id=representative(a,person);agree(id);assertThat(q(id).get("status")).isEqualTo("OFFERED");var newTenant=newParty;f.run(()->changes.confirm(newTenant,id,new Confirm(version(id),q(id).get("content_hash").toString())));assertThat(q(id).get("status")).isEqualTo("AGREED");prepare(id);assertThat(count("contracts","id="+a.contract()+" AND tenant_id=5")).isOne();assertThat(count("contract_change_history","request_id="+id+" AND event_type='CONFIRMED'")).isEqualTo(2);}
 @Test void tc23_repChangeCannotTransferOldDebtOrDeposit(){var a=active();long person=occupant(a);var newParty=newUser(person);long id=representative(a,person);b.oldDebt(a,"500000");f.run(()->changes.offer(f.owner,id,new Action(0,"Checked")));error("CHANGE_STATE_INVALID",()->prepare(id));assertThat(count("contracts","id="+a.contract()+" AND tenant_id=5")).isOne();}
 @Test void tc24_newRepresentativeCanReadOnlyOwnInvitation(){var a=active();long person=occupant(a);var newParty=newUser(person);long id=representative(a,person);var newTenant=newParty;assertThat(changes.invitations(newTenant)).extracting(x->((Number)x.get("id")).longValue()).contains(id);assertThat(changes.requestDetail(newTenant,id).get("requests")).isNotNull();assertThat(((Map<?,?>)changes.requestDetail(newTenant,id).get("contract")).containsKey("deposit_amount")).isFalse();error("CHANGE_ACCESS_DENIED",()->changes.detail(newTenant,a.contract()));}
 @Test void tc25_oldTenantCannotAccessNewSignerContract(){var a=b.active("0",false);f.db.sql("UPDATE rooms SET capacity=4 WHERE id=:id").param("id",a.room()).update();long person=occupant(a);var newParty=newUser(person);long id=representative(a,person);agree(id);f.run(()->changes.confirm(newParty,id,new Confirm(version(id),q(id).get("content_hash").toString())));prepare(id);settle(a,id);roomsReady(a.room());prepare(id);assertThat(new TenantContractRepository(f.db).findContract(5L,target(id))).isEmpty();assertThat(new TenantContractRepository(f.db).findContract(newParty.id(),target(id))).isPresent();}
 void roomsReady(long room){long v=f.db.sql("SELECT version FROM rooms WHERE id=:id").param("id",room).query(Long.class).single();f.run(()->rooms.manual(room,"READY",v,"Cleaning and assets accepted",true,1));}
 @Test void tc26_addResidentRequiresStaffApproval(){var a=active();long id=residentRequest(a,f.key());assertThat(count("tenant_residences","contract_id="+a.contract())).isOne();accept(id);assertThat(count("tenant_residences","contract_id="+a.contract()+" AND status='ACTIVE'")).isEqualTo(2);}
 @Test void tc27_capacityCheckedAgainAtApproval(){var a=active();f.db.sql("UPDATE rooms SET capacity=1 WHERE id=:id").param("id",a.room()).update();long r=residentRequest(a,f.key());error("ROOM_CAPACITY_EXCEEDED",()->accept(r));assertThat(count("co_occupant_requests","id="+r+" AND status='SUBMITTED'")).isOne();}
 @Test void tc28_moveOutKeepsResidenceAndAccount(){var a=active();long person=occupant(a);long r=f.insert("INSERT INTO co_occupant_requests(request_type,property_id,room_id,contract_id,requester_user_id,occupant_profile_id,full_name,reason,idempotency_key) VALUES('MOVE_OUT',"+a.property()+","+a.room()+","+a.contract()+",5,"+person+",'Resident','Actual departure','"+f.key()+"')");accept(r);assertThat(count("tenant_residences","tenant_profile_id="+person+" AND status='MOVED_OUT'")).isOne();assertThat(count("tenant_profiles","id="+person)).isOne();}
 @Test void tc29_personDaysFollowEffectiveResidenceDates(){var a=active();LocalDate month=LocalDate.now().withDayOfMonth(1);f.db.sql("UPDATE tenant_residences SET move_in_date=:date WHERE contract_id=:id").param("date",month).param("id",a.contract()).update();long person=occupant(a);f.db.sql("UPDATE tenant_residences SET move_in_date=:start,move_out_date=:end,status='MOVED_OUT' WHERE tenant_profile_id=:id").param("start",month.plusDays(10)).param("end",month.plusDays(20)).param("id",person).update();assertThat(b.billing.residentDays(a.contract(),month,month.plusMonths(1))).isEqualByComparingTo(BigDecimal.valueOf(month.lengthOfMonth()+10));}
 @Test void tc30_existingIdentityReusedWithoutDuplicateProfile(){var a=active();String identity=f.key();long profile=f.insert("INSERT INTO tenant_profiles(tenant_code,full_name,phone,identity_number) VALUES('"+f.key().substring(0,20)+"','Existing','"+f.key().substring(0,18)+"','"+identity+"')");long r=residentRequest(a,identity);accept(r);assertThat(count("tenant_profiles","identity_number='"+identity+"'")).isOne();assertThat(count("tenant_residences","tenant_profile_id="+profile+" AND contract_id="+a.contract())).isOne();}
 @Test void tc31_otherTenantCannotMutateResidentsOrContract(){var a=active();long r=residentRequest(a,f.key());error("ROOM_ACCESS_DENIED",()->f.run(()->residents.review(f.tenant,r,new ResidentApprovalService.Review(0,true,LocalDate.now(),"proof","No tenant self approval"))));error("CHANGE_ACCESS_DENIED",()->changes.detail(new AuthenticatedUser(6L,"other@test.invalid",RoleCode.TENANT),a.contract()));}
 @Test void tc32_accountantCannotPrepareTransfer(){var a=active();long id=move(a,destination(a),"0");agree(id);error("CHANGE_ACCESS_DENIED",()->f.run(()->changes.prepareMove(f.accountant,id,new Action(version(id),"Forbidden"))));}
 @Test void tc33_importantChangesHaveAudit(){var a=active();long id=extension(a);agree(id);apply(id);assertThat(count("contract_change_history","request_id="+id)).isEqualTo(4);assertThat(count("contract_history","contract_id="+a.contract()+" AND event_type='EXTENSION_APPLIED'")).isOne();}
 @Test void tc34_concurrentResidentApprovalCannotExceedCapacity()throws Exception{var a=active();f.db.sql("UPDATE rooms SET capacity=2 WHERE id=:id").param("id",a.room()).update();long r1=residentRequest(a,f.key()),r2=residentRequest(a,f.key());var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);AtomicInteger ok=new AtomicInteger();var tasks=new ArrayList<Future<?>>();for(long r:List.of(r1,r2))tasks.add(pool.submit(()->{try{start.await();accept(r);ok.incrementAndGet();}catch(Exception ignored){}}));start.countDown();for(var t:tasks)t.get(20,TimeUnit.SECONDS);pool.shutdownNow();assertThat(ok.get()).isOne();assertThat(count("tenant_residences","contract_id="+a.contract()+" AND status='ACTIVE'")).isEqualTo(2);}
 @Test void preparedMoveCanBeCancelledBeforeAnyHandover(){var a=b.active("0",false);long room=destination(a),id=move(a,room,"0");agree(id);prepare(id);f.run(()->changes.cancel(f.owner,id,new Action(version(id),"Tenant withdrew before moving")));assertThat(count("rooms","id="+room+" AND status='VACANT'")).isOne();assertThat(count("rooms","id="+a.room()+" AND status='OCCUPIED'")).isOne();assertThat(q(id).get("status")).isEqualTo("CANCELLED");}
 @Test void crossOwnerTargetRejected(){var a=active();long p=f.insert("INSERT INTO properties(owner_id,code,name,address) VALUES(2,'"+f.key().substring(0,20)+"','Other owner','Test')");long room=f.insert("INSERT INTO rooms(property_id,code,monthly_rent,status) VALUES("+p+",'TARGET',3000000,'READY')");error("TRANSFER_OWNER_MISMATCH",()->move(a,room,"0"));}
